// Note that we don't yet support `indirect` for enums.
// See https://github.com/mozilla/uniffi-rs/issues/396 for further discussion.
/**
 * One annotation shape. All coordinates are absolute pixels.
 * `fill` is `null` for outline-only, `Some(colour)` for a filled shape.
 */

public enum Annotation {
    
    case arrow(from: Point, to: Point, colour: Colour, width: UInt32
    )
    case rect(x: UInt32, y: UInt32, w: UInt32, h: UInt32, colour: Colour, width: UInt32, fill: Colour?
    )
    case ellipse(x: UInt32, y: UInt32, w: UInt32, h: UInt32, colour: Colour, width: UInt32, fill: Colour?
    )
    case line(from: Point, to: Point, colour: Colour, width: UInt32
    )
    case text(x: UInt32, y: UInt32, text: String, size: Float, colour: Colour
    )
}


#if compiler(>=6)
extension Annotation: Sendable {}
#endif

#if swift(>=5.8)
@_documentation(visibility: private)
#endif
public struct FfiConverterTypeAnnotation: FfiConverterRustBuffer {
    typealias SwiftType = Annotation

    public static func read(from buf: inout (data: Data, offset: Data.Index)) throws -> Annotation {
        let variant: Int32 = try readInt(&buf)
        switch variant {
        
        case 1: return .arrow(from: try FfiConverterTypePoint.read(from: &buf), to: try FfiConverterTypePoint.read(from: &buf), colour: try FfiConverterTypeColour.read(from: &buf), width: try FfiConverterUInt32.read(from: &buf)
        )
        
        case 2: return .rect(x: try FfiConverterUInt32.read(from: &buf), y: try FfiConverterUInt32.read(from: &buf), w: try FfiConverterUInt32.read(from: &buf), h: try FfiConverterUInt32.read(from: &buf), colour: try FfiConverterTypeColour.read(from: &buf), width: try FfiConverterUInt32.read(from: &buf), fill: try FfiConverterOptionTypeColour.read(from: &buf)
        )
        
        case 3: return .ellipse(x: try FfiConverterUInt32.read(from: &buf), y: try FfiConverterUInt32.read(from: &buf), w: try FfiConverterUInt32.read(from: &buf), h: try FfiConverterUInt32.read(from: &buf), colour: try FfiConverterTypeColour.read(from: &buf), width: try FfiConverterUInt32.read(from: &buf), fill: try FfiConverterOptionTypeColour.read(from: &buf)
        )
        
        case 4: return .line(from: try FfiConverterTypePoint.read(from: &buf), to: try FfiConverterTypePoint.read(from: &buf), colour: try FfiConverterTypeColour.read(from: &buf), width: try FfiConverterUInt32.read(from: &buf)
        )
        
        case 5: return .text(x: try FfiConverterUInt32.read(from: &buf), y: try FfiConverterUInt32.read(from: &buf), text: try FfiConverterString.read(from: &buf), size: try FfiConverterFloat.read(from: &buf), colour: try FfiConverterTypeColour.read(from: &buf)
        )
        
        default: throw UniffiInternalError.unexpectedEnumCase
        }
    }

    public static func write(_ value: Annotation, into buf: inout [UInt8]) {
        switch value {
        
        
        case let .arrow(from,to,colour,width):
            writeInt(&buf, Int32(1))
            FfiConverterTypePoint.write(from, into: &buf)
            FfiConverterTypePoint.write(to, into: &buf)
            FfiConverterTypeColour.write(colour, into: &buf)
            FfiConverterUInt32.write(width, into: &buf)
            
        
        case let .rect(x,y,w,h,colour,width,fill):
            writeInt(&buf, Int32(2))
            FfiConverterUInt32.write(x, into: &buf)
            FfiConverterUInt32.write(y, into: &buf)
            FfiConverterUInt32.write(w, into: &buf)
            FfiConverterUInt32.write(h, into: &buf)
            FfiConverterTypeColour.write(colour, into: &buf)
            FfiConverterUInt32.write(width, into: &buf)
            FfiConverterOptionTypeColour.write(fill, into: &buf)
            
        
        case let .ellipse(x,y,w,h,colour,width,fill):
            writeInt(&buf, Int32(3))
            FfiConverterUInt32.write(x, into: &buf)
            FfiConverterUInt32.write(y, into: &buf)
            FfiConverterUInt32.write(w, into: &buf)
            FfiConverterUInt32.write(h, into: &buf)
            FfiConverterTypeColour.write(colour, into: &buf)
            FfiConverterUInt32.write(width, into: &buf)
            FfiConverterOptionTypeColour.write(fill, into: &buf)
            
        
        case let .line(from,to,colour,width):
            writeInt(&buf, Int32(4))
            FfiConverterTypePoint.write(from, into: &buf)
            FfiConverterTypePoint.write(to, into: &buf)
            FfiConverterTypeColour.write(colour, into: &buf)
            FfiConverterUInt32.write(width, into: &buf)
            
        
        case let .text(x,y,text,size,colour):
            writeInt(&buf, Int32(5))
            FfiConverterUInt32.write(x, into: &buf)
            FfiConverterUInt32.write(y, into: &buf)
            FfiConverterString.write(text, into: &buf)
            FfiConverterFloat.write(size, into: &buf)
            FfiConverterTypeColour.write(colour, into: &buf)
            
        }
    }
}


