// Note that we don't yet support `indirect` for enums.
// See https://github.com/mozilla/uniffi-rs/issues/396 for further discussion.
/**
 * One of the ten tools, with its options, for `bulk_process`.
 * `CompressToSize` is a UniFFI-only variant (see DIVERGENCE note).
 * `Collage` is present so the ten tools map 1:1, but it is NOT a
 * per-item op: `bulk_process` returns `INVALID_ARGUMENT` for every
 * item — call `make_collage` once with the full list instead.
 */

public enum BulkOp {
    
    case compress(options: CompressOptions
    )
    case compressToSize(options: CompressOptions, targetBytes: UInt64
    )
    case resize(options: ResizeOptions
    )
    case crop(options: CropOptions
    )
    case convert(options: ConvertOptions
    )
    case watermark(options: WatermarkOptions
    )
    case annotate(annotations: [Annotation]
    )
    case pickColour(x: UInt32, y: UInt32
    )
    case palette(count: UInt8
    )
    case collage(options: CollageOptions
    )
    case pixelate(options: PixelateOptions
    )
}


#if compiler(>=6)
extension BulkOp: Sendable {}
#endif

#if swift(>=5.8)
@_documentation(visibility: private)
#endif
public struct FfiConverterTypeBulkOp: FfiConverterRustBuffer {
    typealias SwiftType = BulkOp

    public static func read(from buf: inout (data: Data, offset: Data.Index)) throws -> BulkOp {
        let variant: Int32 = try readInt(&buf)
        switch variant {
        
        case 1: return .compress(options: try FfiConverterTypeCompressOptions.read(from: &buf)
        )
        
        case 2: return .compressToSize(options: try FfiConverterTypeCompressOptions.read(from: &buf), targetBytes: try FfiConverterUInt64.read(from: &buf)
        )
        
        case 3: return .resize(options: try FfiConverterTypeResizeOptions.read(from: &buf)
        )
        
        case 4: return .crop(options: try FfiConverterTypeCropOptions.read(from: &buf)
        )
        
        case 5: return .convert(options: try FfiConverterTypeConvertOptions.read(from: &buf)
        )
        
        case 6: return .watermark(options: try FfiConverterTypeWatermarkOptions.read(from: &buf)
        )
        
        case 7: return .annotate(annotations: try FfiConverterSequenceTypeAnnotation.read(from: &buf)
        )
        
        case 8: return .pickColour(x: try FfiConverterUInt32.read(from: &buf), y: try FfiConverterUInt32.read(from: &buf)
        )
        
        case 9: return .palette(count: try FfiConverterUInt8.read(from: &buf)
        )
        
        case 10: return .collage(options: try FfiConverterTypeCollageOptions.read(from: &buf)
        )
        
        case 11: return .pixelate(options: try FfiConverterTypePixelateOptions.read(from: &buf)
        )
        
        default: throw UniffiInternalError.unexpectedEnumCase
        }
    }

    public static func write(_ value: BulkOp, into buf: inout [UInt8]) {
        switch value {
        
        
        case let .compress(options):
            writeInt(&buf, Int32(1))
            FfiConverterTypeCompressOptions.write(options, into: &buf)
            
        
        case let .compressToSize(options,targetBytes):
            writeInt(&buf, Int32(2))
            FfiConverterTypeCompressOptions.write(options, into: &buf)
            FfiConverterUInt64.write(targetBytes, into: &buf)
            
        
        case let .resize(options):
            writeInt(&buf, Int32(3))
            FfiConverterTypeResizeOptions.write(options, into: &buf)
            
        
        case let .crop(options):
            writeInt(&buf, Int32(4))
            FfiConverterTypeCropOptions.write(options, into: &buf)
            
        
        case let .convert(options):
            writeInt(&buf, Int32(5))
            FfiConverterTypeConvertOptions.write(options, into: &buf)
            
        
        case let .watermark(options):
            writeInt(&buf, Int32(6))
            FfiConverterTypeWatermarkOptions.write(options, into: &buf)
            
        
        case let .annotate(annotations):
            writeInt(&buf, Int32(7))
            FfiConverterSequenceTypeAnnotation.write(annotations, into: &buf)
            
        
        case let .pickColour(x,y):
            writeInt(&buf, Int32(8))
            FfiConverterUInt32.write(x, into: &buf)
            FfiConverterUInt32.write(y, into: &buf)
            
        
        case let .palette(count):
            writeInt(&buf, Int32(9))
            FfiConverterUInt8.write(count, into: &buf)
            
        
        case let .collage(options):
            writeInt(&buf, Int32(10))
            FfiConverterTypeCollageOptions.write(options, into: &buf)
            
        
        case let .pixelate(options):
            writeInt(&buf, Int32(11))
            FfiConverterTypePixelateOptions.write(options, into: &buf)
            
        }
    }
}


